"""Actual homepage promotion checks, not a test of the separate preview.
The V13 HTML remains the no-script fallback. Browser assertions target the open
shadow root that is actually painted, never the hidden fallback directories.
"""
from pathlib import Path

def home(page,check,label,deep=False,out=None):
    page.wait_for_selector('body[data-atelier-ready=true]')
    page.evaluate('document.fonts.ready')
    def ck(ok,desc):check(ok,label+': '+desc)
    ck(page.locator('body').get_attribute('data-spatial14')=='ready','spatial design mounted on official homepage')
    ck(page.locator('#thoughts').get_attribute('data-spatial14')=='ready','same official thought anchor')
    ck(page.locator('h1').count()==1 and page.locator('#hero-title').is_visible(),'one unchanged homepage headline')
    ck(page.locator('.word-tag').count()==4 and page.locator('#why .manifesto-body').is_visible(),'colored words and manifesto retained')
    ck(page.locator('main>section').evaluate_all('es=>es.map(e=>e.id)')==['top','why','archive','thoughts','context','how','story','get-paia'],'existing narrative order retained')
    ck(page.locator('#archive .p13-input').count()==4,'archive still presents its complete collection')
    ck(page.locator('#thoughts .sp14 .topic').count()==3,'three visible spatial topic objects')
    ck(page.locator('#thoughts .sp14 .chapter-list>span').count()==9,'actual topic chapters retained')
    ck(page.locator('#thoughts .sp14 .topic p,#thoughts .sp14 input,#thoughts .sp14 [contenteditable]').count()==0,'no invented excerpts, search or edit modes')
    ck(page.locator('#thoughts .sp14 .reader .entry').count()==2,'selected reading scope remains two complete inputs')
    ck(page.locator('#thoughts .sp14 .entry time').evaluate_all('es=>es.map(e=>e.getAttribute("datetime"))')==['2026-09-18T21:06','2026-09-12T10:32'],'original dates and newest-first order')
    ck(page.evaluate('(()=>{const h=document.querySelector("#thoughts"),s=h.shadowRoot;return JSON.stringify([...h.querySelectorAll(".p13-entry-body p")].map(e=>e.textContent))===JSON.stringify([...s.querySelectorAll(".entry p")].map(e=>e.textContent))})()'),'rendered reading words equal the real existing fixture')
    ck(page.locator('.p13-detail-grid>.p13-detail-card').count()==3,'daily details unchanged')
    ck(page.locator('.privacy-art .privacy-ring').count()==2,'privacy orbit retained')
    ck(page.locator('.privacy-home img').evaluate('e=>e.complete&&e.naturalWidth>0'),'original privacy mark available')
    ck(page.locator('#context .context-card').count()==4,'approved Context quartet retained')
    ck(page.locator('#context [contenteditable]').count()==0,'Context overview remains directories only')
    ck(page.locator('#prompt-draft').get_attribute('readonly') is not None,'presentation never overwrites visitor-authored text')
    ck(page.locator('.p13-boundary').is_visible(),'fictional no-connection boundary retained')
    ck(page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'),'normal reflow')
    if page.viewport_size['width']<=700:
        ck(page.locator('.p13-private').evaluate('e=>e.querySelector(".text-arrow").getBoundingClientRect().bottom+5<e.querySelector(".privacy-art").getBoundingClientRect().top'),'privacy text never collides with art')
    if page.locator('.menu-toggle').is_visible():
        b=page.locator('.menu-toggle');b.focus();page.keyboard.press('Enter')
        ck(page.locator('#mobile-nav').is_visible(),'mobile menu opens by keyboard')
        page.keyboard.press('Escape');ck(not page.locator('#mobile-nav').is_visible() and b.evaluate('e=>e===document.activeElement'),'Escape restores menu focus')
    page.emulate_media(reduced_motion='reduce')
    page.wait_for_function('document.querySelector("#thoughts").shadowRoot.querySelector(".sp14").dataset.motion==="static"')
    ck(page.locator('#thoughts .sp14 .reader').is_visible(),'reduced motion presents complete reading surface')
    ck(page.locator('#thoughts .sp14 .intro h2').is_visible(),'reduced motion retains section heading')
    ck(page.locator('#thoughts .sp14 .entry p').count()==4,'no paragraph replaced by a teaser')
    ck(page.locator('#thoughts .sp14 .reader-body').evaluate('e=>getComputedStyle(e).overflowY==="auto"'),'long prose remains reachable')
    ck(page.evaluate('getComputedStyle(document.documentElement).scrollBehavior==="auto"'),'system reduced motion applies to page scroll')
    if out:
        dest=Path(out);dest.mkdir(parents=True,exist_ok=True)
        page.evaluate("scrollTo({top:0,behavior:'instant'})")
        page.screenshot(path=str(dest/(label.replace('/','-')+'-hero.png')),animations='disabled')
        page.locator('#thoughts').screenshot(path=str(dest/(label.replace('/','-')+'-spatial-static.png')),animations='disabled')
    if not deep:return
    # Native page scroll must work at the real section offset, not only at y=0.
    page.emulate_media(reduced_motion='no-preference')
    page.wait_for_function('document.querySelector("#thoughts").shadowRoot.querySelector(".sp14").dataset.motion==="scroll"')
    page.evaluate('window.__spatialNodes=[...document.querySelector("#thoughts").shadowRoot.querySelectorAll(".entry p")]')
    text=page.locator('#thoughts .sp14 .entry p').all_text_contents()
    for progress in [0,.58,.92,0]:
        page.evaluate('p=>{const h=document.querySelector("#thoughts").shadowRoot,e=h.querySelector(".experience"),s=h.querySelector(".sticky-scene");scrollTo({top:e.getBoundingClientRect().top+scrollY+p*(e.offsetHeight-s.clientHeight),behavior:"instant"});dispatchEvent(new Event("scroll"))}',progress)
        page.wait_for_function('p=>Math.abs(Number(getComputedStyle(document.querySelector("#thoughts").shadowRoot.querySelector(".sp14")).getPropertyValue("--progress"))-p)<.03',arg=progress,timeout=8000)
        ck(page.locator('#thoughts .sp14 .entry p').all_text_contents()==text,'scroll preserves every word at '+str(progress))
        ck(page.evaluate('window.__spatialNodes.every((e,i)=>e===document.querySelector("#thoughts").shadowRoot.querySelectorAll(".entry p")[i])'),'scroll preserves content node identity at '+str(progress))
        ck(page.locator('#thoughts .sp14 .sticky-scene').evaluate('e=>Math.abs(e.getBoundingClientRect().top)<3'),'native sticky stage holds at '+str(progress))
        ck(page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'),'spatial reflow at '+str(progress))
    page.locator('#thoughts .sp14 [data-view=".92"]').click()
    page.wait_for_function('document.querySelector("#thoughts").shadowRoot.querySelector(".sp14").dataset.view==="2"')
    ck(page.locator('#thoughts .sp14 .projection').evaluate('e=>getComputedStyle(e).transform==="none"'),'read view is precise and front-facing')
    page.emulate_media(reduced_motion='reduce')
    switches=page.locator('.context-switch');master=page.locator('#context [data-ctx-master]')
    ck(switches.evaluate_all('es=>es.every(e=>e.getAttribute("aria-checked")==="false")'),'permissions default off')
    page.locator('#context [data-ctx-open=information]').first.click()
    ck(page.locator('#context-dialog').is_visible() and switches.nth(0).get_attribute('aria-checked')=='false','viewing never grants access')
    page.keyboard.press('Escape');switches.nth(1).click();master.click();master.click()
    ck(switches.nth(1).get_attribute('aria-checked')=='true' and master.get_attribute('aria-checked')=='false','pause retains subordinate choices')
    page.locator('#context [data-ctx-open=inputs]').first.click();page.locator('[data-topic-permission=product]').click()
    ck(master.get_attribute('aria-checked')=='false' and switches.nth(3).get_attribute('aria-checked')=='false','Topic choice does not grant parents')
    page.locator('[data-ctx-topic=product]').click()
    ck(page.locator('#context-dialog [contenteditable]').count()==0,'scope inspection stays read-only')
    page.keyboard.press('Escape');ck(not page.locator('#context-dialog').is_visible(),'Escape closes after modal content changes')
    draft=page.locator('#prompt-draft');draft.scroll_into_view_if_needed();page.locator('#r3-host .ps-anchor').click()
    ck(page.locator('#r3-host .ps-board').is_visible() and page.locator('#r3-host .ps-row').count()==6,'authentic six-row R3 still opens')
    page.locator('#r3-host .ps-row button').first.click()
    ck(len(draft.input_value().splitlines())>=2,'reuse preserves initial draft line')
    ck(page.locator('#reuse').get_attribute('data-story-state')=='paused','manual R3 operation takes ownership')
    ck(not page.evaluate('localStorage.length||sessionStorage.length'),'no private persistence')
    page.emulate_media(forced_colors='active')
    ck(page.locator('#hero-title').evaluate('e=>getComputedStyle(e).color!=="transparent"'),'high contrast hero readable')
    ck(page.locator('#thoughts .sp14 .reader').is_visible(),'high contrast spatial content remains available')
    page.emulate_media(forced_colors='none')
